// GENERATED by crashtest. Crash point "post-settle": SIGKILL once right after eve records call.settled.
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { defineHook } from "eve/hooks";

export default defineHook({
  events: {
    "call.settled"() {
      const run = process.env.CT_RUN_DIR;
      if (process.env.CT_CRASH_POINT !== "post-settle" || !run) return;
      try { writeFileSync(join(run, "crashed.marker"), `post-settle pid=${process.pid}`, { flag: "wx" }); } catch { return; }
      process.kill(process.pid, "SIGKILL");
    },
  },
});
